#!/usr/bin/env bun
/**
 * The Lua the host embeds, written next to the other generated files:
 *
 *   types/generated/prelude.lua  <- lua/prelude.lua   (`utf8`, which the app environment does not copy from Luau)
 *   types/generated/docker.luau  <- crates/vos-lua/lua/docker/main.luau, bundled with what it requires as an app's
 *                                   backend is (darklua: scripts/luau.ts). It is `vos:docker`, the container framework.
 *
 *   bun scripts/codegen-lua.ts          write it (part of `bun run codegen`)
 *   bun scripts/codegen-lua.ts --check  exit 1 when it is missing or stale (part of `bun run codegen:check`)
 *
 * Never edit the output by hand.
 */
import { existsSync, readFileSync, writeFileSync } from 'node:fs'
import { join, resolve } from 'node:path'
import { requireDarklua, toLuau } from './luau'

const root = resolve(import.meta.dir, '..')
const TARGETS = [
  { from: 'lua/prelude.lua', to: 'types/generated/prelude.lua', bundle: false },
  { from: 'crates/vos-lua/lua/docker/main.luau', to: 'types/generated/docker.luau', bundle: true }
]

const mode = process.argv[2]
if (mode !== undefined && mode !== '--check') {
  console.error('usage: bun scripts/codegen-lua.ts [--check]')
  process.exit(2)
}

const stale: string[] = []
for (const { from, to, bundle } of TARGETS) {
  // a bundle keeps its lines where darklua put them (an error names them), so its header is one line at the end
  const contents = bundle
    ? `${toLuau(requireDarklua(), join(root, from))}\n-- GENERATED by scripts/codegen-lua.ts: ${from}, bundled. Do not edit.\n`
    : `-- GENERATED by scripts/codegen-lua.ts: a copy of ${from}. Do not edit.\n${readFileSync(join(root, from), 'utf8')}`
  const target = join(root, to)
  if (mode === '--check') {
    if (!existsSync(target) || readFileSync(target, 'utf8') !== contents) stale.push(to)
  } else {
    writeFileSync(target, contents)
    console.log(`wrote ${to}`)
  }
}

if (mode === '--check') {
  if (stale.length > 0) {
    console.error('codegen:check FAILED: these generated Lua files are stale:')
    for (const path of stale) console.error(`  ${path}`)
    console.error('run `bun run codegen` and commit the result')
    process.exit(1)
  }
  console.log(`codegen:check OK (${TARGETS.length} generated Lua files up to date)`)
}
